package de.nevergate.fahrzeuge;
import java.util.*;
import net.minecraft.core.BlockPos;
import net.minecraft.gametest.framework.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.*;
import net.minecraft.world.InteractionHand;
import net.minecraftforge.gametest.GameTestHolder;
@GameTestHolder(value=NgFahrzeuge.MOD_ID,namespace=NgFahrzeuge.MOD_ID)
public final class Dev12GameTests {
 private static NgCityEntity car(GameTestHelper h,VehicleSpec s){var c=VehicleContent.type(s).create(h.getLevel());var b=h.absolutePos(new BlockPos(1,1,1));c.setPos(b.getX()+.5,h.getLevel().getMaxBuildHeight()-40,b.getZ()+.5);c.setNoGravity(true);h.getLevel().addFreshEntity(c);return c;}
 private static Player player(GameTestHelper h,NgCityEntity c){var p=h.makeMockPlayer();p.setUUID(UUID.randomUUID());p.getAbilities().mayBuild=true;p.getAbilities().instabuild=false;p.setPos(c.position());return p;}
 private static Player owner(GameTestHelper h,NgCityEntity c){var p=player(h,c);c.equipment.claim(p);return p;}
 private static void start(NgCityEntity c,Player p){p.startRiding(c);c.applyAction(p,2);c.applyAction(p,0);}
 private static TrailerEntity semi(GameTestHelper h,NgCityEntity c,Player p){var t=VehicleContent.TRAILER.get().create(h.getLevel());t.variant(3);t.setPos(c.position().add(0,0,-4.15));t.setNoGravity(true);t.claim(p);h.getLevel().addFreshEntity(t);return t;}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void newTypesSeatCapacityAndPackedIdentity(GameTestHelper h){for(var s:new VehicleSpec[]{VehicleSpec.OFFROAD,VehicleSpec.SPORT,VehicleSpec.TAXI,VehicleSpec.TRACTOR}){var c=car(h,s);var p=owner(h,c);for(int i=0;i<s.seats;i++)h.assertTrue(player(h,c).startRiding(c),"Missing seat "+s);h.assertFalse(player(h,c).startRiding(c),"Capacity exceeded "+s);h.assertTrue(c.getPassengers().stream().map(c::getPassengerRidingPosition).distinct().count()==s.seats,"Seats overlap "+s);var copy=VehicleContent.type(s).create(h.getLevel());copy.loadEquipment(c.getPickResult().getTag());h.assertTrue(copy.spec()==s&&copy.equipment.owner().equals(p.getUUID()),"Packed type/owner lost");c.discard();}h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void allWheelAndLowRangeRequireOffroadAndStationary(GameTestHelper h){var c=car(h,VehicleSpec.OFFROAD);var p=owner(h,c);p.startRiding(c);h.assertFalse(c.applyAction(p,25),"Low enabled without AWD");h.assertTrue(c.applyAction(p,24)&&c.systems.mechanics.awd()&&c.applyAction(p,25)&&c.systems.mechanics.low(),"AWD/low did not enable");c.applyAction(p,0);h.assertFalse(c.applyAction(p,24),"AWD changed with brake released");c.applyAction(p,0);c.applyAction(p,24);h.assertFalse(c.systems.mechanics.low(),"Low remained after AWD off");c.discard();var sport=car(h,VehicleSpec.SPORT);var q=owner(h,sport);q.startRiding(sport);h.assertFalse(sport.applyAction(q,24),"Sports car gained AWD");sport.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void lowRangeLimitsSpeedAndImprovesOffroadStep(GameTestHelper h){var c=car(h,VehicleSpec.OFFROAD);var p=owner(h,c);p.startRiding(c);c.applyAction(p,24);c.applyAction(p,25);h.assertTrue(c.systems.speed(.4F,1,false,false)<=.42F*.45F+.001,"Low gear limit missing");h.assertTrue(c.maxUpStep()>=1,"Offroad step clearance unchanged");c.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void hillAssistHoldsThenReleasesAgainstActualSlope(GameTestHelper h){var c=car(h,VehicleSpec.OFFROAD);var p=owner(h,c);start(c,p);c.setOnGround(true);var pos=c.blockPosition();h.getLevel().setBlockAndUpdate(pos.offset(0,-1,1),net.minecraft.world.level.block.Blocks.STONE.defaultBlockState());h.getLevel().setBlockAndUpdate(pos.offset(0,-2,-1),net.minecraft.world.level.block.Blocks.STONE.defaultBlockState());h.assertTrue(c.systems.speed(0,0,false,false)<0,"Fixture did not roll down slope");c.systems.speed(0,0,true,false);for(int i=0;i<40;i++)h.assertTrue(c.systems.speed(0,0,false,false)==0,"Hill hold released too early");h.assertTrue(c.systems.speed(0,0,false,false)<0,"Hill hold never released");c.systems.speed(0,0,true,false);c.applyAction(p,26);h.assertTrue(c.systems.mechanics.hillTicks()==0&&c.systems.speed(0,0,false,false)<0,"Disabled hill assist continued holding");h.getLevel().removeBlock(pos.offset(0,-1,1),false);h.getLevel().removeBlock(pos.offset(0,-2,-1),false);c.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void sportsCarHasHigherServerSpeedLimit(GameTestHelper h){var c=car(h,VehicleSpec.SPORT);var p=owner(h,c);start(c,p);float v=0;for(int i=0;i<200;i++)v=c.systems.speed(v,1,false,false);h.assertTrue(v>.65&&v<=.72001,"Sport speed cap incorrect");c.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void automaticTransmissionChangesGearAndRpm(GameTestHelper h){var c=car(h,VehicleSpec.SPORT);var p=owner(h,c);start(c,p);c.acceptInput(p,1);for(int i=0;i<40;i++)c.tick();h.assertTrue(c.systems.mechanics.gear()>1&&c.systems.mechanics.rpm()>800,"Automatic gearbox/RPM not live");c.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void manualNeutralAndReverseAreDirectionSafe(GameTestHelper h){var c=car(h,VehicleSpec.CITY);var p=owner(h,c);p.startRiding(c);h.assertTrue(c.applyAction(p,27)&&c.applyAction(p,29)&&c.systems.mechanics.gear()==0,"Manual neutral unavailable");h.assertTrue(c.systems.speed(0,1,false,false)==0,"Neutral accelerated");h.assertTrue(c.applyAction(p,29)&&c.systems.mechanics.gear()==-1,"Reverse gear unavailable");h.assertTrue(c.systems.speed(0,1,false,false)==0&&c.systems.speed(0,-1,false,false)<0,"Reverse gear accepted forward motion");c.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void manualFirstGearHasRealLimitAndCannotToggleWhileUnparked(GameTestHelper h){var c=car(h,VehicleSpec.SPORT);var p=owner(h,c);p.startRiding(c);c.applyAction(p,27);h.assertTrue(c.systems.speed(.4F,1,false,false)<=.15001,"First gear did not limit speed");c.applyAction(p,0);h.assertFalse(c.applyAction(p,27),"Gearbox mode changed unparked");c.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void taxiFreeAndOccupiedFollowActualPassengers(GameTestHelper h){var c=car(h,VehicleSpec.TAXI);var p=owner(h,c);p.startRiding(c);h.assertTrue(c.systems.mechanics.taxiFree(),"Driver marked taxi occupied");var q=player(h,c);q.startRiding(c);h.assertFalse(c.systems.mechanics.taxiFree(),"Passenger did not mark taxi occupied");q.stopRiding();h.assertTrue(c.systems.mechanics.taxiFree()&&c.applyAction(p,30)&&!c.systems.mechanics.taxiEnabled(),"Taxi sign control/state wrong");c.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void independentDoorsBlockDrivingAndPersist(GameTestHelper h){var c=car(h,VehicleSpec.FAMILY);var p=owner(h,c);p.startRiding(c);h.assertTrue(c.applyAction(p,32)&&c.systems.mechanics.doorMask()==1&&c.systems.doors()==1,"Front-left door not independent");h.assertTrue(c.applyAction(p,35)&&c.systems.mechanics.doorMask()==9,"Rear-right door changed wrong panel");var copy=VehicleContent.NG_FAMILY.get().create(h.getLevel());copy.loadEquipment(c.getPickResult().getTag());h.assertTrue(copy.systems.mechanics.doorMask()==9,"Individual doors not saved");c.systems.closeDoors();h.assertTrue(c.systems.mechanics.doorMask()==0&&c.systems.doors()==0,"Closing all doors left panel open");c.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void rearDoorControlsRejectTwoSeatVehiclesAndPassengers(GameTestHelper h){var c=car(h,VehicleSpec.PICKUP);var p=owner(h,c);p.startRiding(c);var q=player(h,c);q.startRiding(c);h.assertFalse(c.applyAction(p,34)||c.applyAction(q,32),"Invalid door or passenger control accepted");h.assertTrue(c.applyAction(p,33)&&c.systems.mechanics.doorMask()==2,"Front-right door rejected");c.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void semiHas108PersistentCargoSlots(GameTestHelper h){var c=car(h,VehicleSpec.TRACTOR);var p=owner(h,c);var t=semi(h,c,p);t.cargo.setItem(107,new ItemStack(Items.DIAMOND,9));var copy=VehicleContent.TRAILER.get().create(h.getLevel());copy.loadEquipment(t.getPickResult().getTag());h.assertTrue(copy.variant()==3&&copy.cargo.getContainerSize()==108&&copy.cargo.getItem(107).getCount()==9&&copy.supports(),"Last semi cargo slot/supports lost");h.assertTrue(t.getPickResult().is(VehicleContent.SEMI_TRAILER.get()),"Wrong packed trailer item");c.discard();t.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void fifthWheelNeedsCompatibleVehicleAndRaisedSupportsForStart(GameTestHelper h){var c=car(h,VehicleSpec.TRACTOR);var p=owner(h,c);var t=semi(h,c,p);h.assertTrue(c.systems.couple(p)&&t.towId().equals(c.getUUID()),"Fifth wheel failed");p.startRiding(c);h.assertFalse(c.applyAction(p,2),"Engine started with deployed supports");h.assertTrue(t.toggleSupports(p)&&!t.supports()&&c.applyAction(p,2),"Retracted supports did not permit engine");h.assertFalse(t.toggleSupports(p),"Supports moved with engine running");c.discard();t.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void uncouplingRequiresDeployedSupportsAndNoOpenCargo(GameTestHelper h){var c=car(h,VehicleSpec.TRACTOR);var p=owner(h,c);var t=semi(h,c,p);c.systems.couple(p);t.toggleSupports(p);h.assertFalse(c.systems.couple(p),"Semi detached without supports");t.toggleSupports(p);t.cargo.startOpen(p);h.assertFalse(c.systems.couple(p),"Semi detached while viewed");p.setShiftKeyDown(true);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(VehicleContent.PAPERS.get()));h.assertTrue(t.interact(p,InteractionHand.MAIN_HAND)==net.minecraft.world.InteractionResult.FAIL,"Papers bypassed active cargo viewer");p.setShiftKeyDown(false);p.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);t.cargo.stopOpen(p);h.assertTrue(c.systems.couple(p)&&t.towId()==null,"Supported semi did not detach");c.discard();t.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void pickupCannotCoupleSemiAndTractorCannotCoupleNormalTrailer(GameTestHelper h){var c=car(h,VehicleSpec.PICKUP);var p=owner(h,c);var t=semi(h,c,p);h.assertFalse(c.systems.couple(p),"Pickup coupled semitrailer");c.discard();t.discard();var truck=car(h,VehicleSpec.TRACTOR);var q=owner(h,truck);var small=VehicleContent.TRAILER.get().create(h.getLevel());small.setPos(truck.position().add(0,0,-4));small.claim(q);h.getLevel().addFreshEntity(small);h.assertFalse(truck.systems.couple(q),"Tractor accepted drawbar trailer");truck.discard();small.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void semiPagesShareOriginalInventoryAndCountOpeners(GameTestHelper h){var c=car(h,VehicleSpec.TRACTOR);var p=owner(h,c);var t=semi(h,c,p);p.setPos(t.position());var menu=new TrailerCargoMenu(1,p.getInventory(),t.getId(),1);h.assertTrue(t.hasOpeners(),"Second page not original slots or opener missing");menu.slots.get(53).set(new ItemStack(Items.GOLD_INGOT,3));h.assertTrue(t.cargo.getItem(107).getCount()==3,"Page copied cargo instead of referencing it");menu.removed(p);h.assertFalse(t.hasOpeners(),"Closed page retained opener");c.discard();t.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void semiGeometryAndCouplingSurviveEntitySave(GameTestHelper h){var c=car(h,VehicleSpec.TRACTOR);var p=owner(h,c);var t=semi(h,c,p);c.systems.couple(p);t.toggleSupports(p);var tag=new CompoundTag();t.saveWithoutId(tag);var copy=VehicleContent.TRAILER.get().create(h.getLevel());copy.load(tag);h.assertTrue(copy.variant()==3&&copy.towId().equals(c.getUUID())&&!copy.supports()&&copy.getBoundingBox().getZsize()==8&&Math.abs(copy.getBoundingBox().getXsize()-2.5)<.001,"Saved semi identity/geometry changed");c.discard();t.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void remoteKeyLocksOnlyUniqueAuthorizedLoadedVehicle(GameTestHelper h){var c=car(h,VehicleSpec.CITY);var p=owner(h,c);var key=new ItemStack(VehicleContent.KEY.get());p.setItemInHand(InteractionHand.MAIN_HAND,key);h.assertTrue(c.equipment.bindKey(p,key),"Key bind failed");p.setPos(c.position().add(12,0,0));h.assertTrue(key.getItem().use(h.getLevel(),p,InteractionHand.MAIN_HAND).getResult().consumesAction()&&c.isLocked(),"Remote failed at distance");p.setPos(c.position().add(40,0,0));key.getItem().use(h.getLevel(),p,InteractionHand.MAIN_HAND);h.assertTrue(c.isLocked(),"Out-of-range remote changed lock");c.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void revokedKeyCannotUseRemote(GameTestHelper h){var c=car(h,VehicleSpec.CITY);var p=owner(h,c);var key=new ItemStack(VehicleContent.KEY.get());c.equipment.bindKey(p,key);h.assertTrue(c.equipment.revokeKeys(p),"Key revocation failed");p.setItemInHand(InteractionHand.MAIN_HAND,key);h.assertFalse(key.getItem().use(h.getLevel(),p,InteractionHand.MAIN_HAND).getResult().consumesAction()||c.isLocked(),"Revoked remote worked");c.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void cargoLockIsIndependentOfCabinAndStopsCargoOpen(GameTestHelper h){var c=car(h,VehicleSpec.FAMILY);var p=owner(h,c);h.assertTrue(c.systems.mechanics.toggleCargoLock(p)&&!c.isLocked()&&!c.equipment.canOpen(p),"Cargo lock did not isolate compartment");p.startRiding(c);h.assertFalse(c.applyAction(p,9)||c.applyAction(p,7),"Locked cargo opened");p.stopRiding();h.assertTrue(c.systems.mechanics.toggleCargoLock(p)&&c.equipment.canOpen(p),"Cargo did not unlock");c.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void heavyDamageEnablesHazardsAndDamagesRadiator(GameTestHelper h){var c=car(h,VehicleSpec.CITY);c.systems.damage(5);h.assertTrue(c.signal()==0,"Minor damage enabled hazards");c.systems.damage(25);h.assertTrue(c.signal()==3&&c.systems.mechanics.radiator()<90,"Heavy damage did not trigger hazards/radiator loss");c.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void emptyCoolingSystemOverheatsAndStopsEngine(GameTestHelper h){var c=car(h,VehicleSpec.CITY);var p=owner(h,c);start(c,p);var tag=new CompoundTag();c.systems.save(tag);tag.putFloat("Temperature",129.99F);tag.putFloat("Coolant",0);c.systems.load(tag);c.systems.mechanics.tick(1);h.assertTrue(c.systems.mechanics.temperature()>=130&&!c.engineRunning(),"Overheat did not stop engine");c.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void damagedRadiatorLeaksActualExistingCoolant(GameTestHelper h){var c=car(h,VehicleSpec.CITY);var p=owner(h,c);start(c,p);c.systems.mechanics.impact(100);float before=c.systems.mechanics.coolant();for(int i=0;i<100;i++)c.systems.mechanics.tick(0);h.assertTrue(c.systems.mechanics.coolant()<before&&c.systems.mechanics.temperature()>20,"Damaged cooling did not leak/heat");c.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void coolantCanPreservesRemainderAndRequiresColdOpenHood(GameTestHelper h){var c=car(h,VehicleSpec.CITY);var p=owner(h,c);var can=new ItemStack(VehicleContent.COOLANT.get());var tag=new CompoundTag();c.systems.save(tag);tag.putFloat("Coolant",4.6F);c.systems.load(tag);h.assertFalse(VehicleCoolantItem.fill(c,p,can),"Coolant filled through closed hood");c.systems.upgrades.action(p,16);h.assertTrue(VehicleCoolantItem.fill(c,p,can)&&Math.abs(c.systems.mechanics.coolant()-5)<.0001&&VehicleCoolantItem.remaining(can)==3600,"Partial coolant transfer created/lost liquid");tag=new CompoundTag();c.systems.save(tag);tag.putFloat("Coolant",0);tag.putFloat("Temperature",90);c.systems.load(tag);h.assertFalse(VehicleCoolantItem.fill(c,p,can)||VehicleCoolantItem.remaining(can)!=3600,"Hot refill accepted/consumed liquid");c.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void repairRestoresRadiatorAndDiagnosisCountsRealParts(GameTestHelper h){var c=car(h,VehicleSpec.CITY);var p=owner(h,c);c.systems.damage(50);h.assertTrue(c.systems.mechanics.repairParts()==2&&c.systems.mechanics.diagnosis().contains("Ersatzteile mindestens: 2"),"Diagnosis part count wrong");p.getInventory().setItem(8,new ItemStack(VehicleContent.PARTS.get(),2));var tool=new ItemStack(VehicleContent.REPAIR_TOOL.get());float radiator=c.systems.mechanics.radiator();h.assertTrue(c.systems.repair(p,tool)&&c.systems.mechanics.radiator()>radiator&&p.getInventory().getItem(8).getCount()==1,"Repair did not reuse parts/radiator state");c.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void mechanicsStatePersistsAndRejectsInvalidNumbers(GameTestHelper h){var c=car(h,VehicleSpec.OFFROAD);var p=owner(h,c);p.startRiding(c);c.applyAction(p,24);c.applyAction(p,25);c.applyAction(p,27);c.applyAction(p,28);var tag=new CompoundTag();c.systems.save(tag);tag.putFloat("Temperature",Float.NaN);tag.putFloat("Radiator",-999);tag.putFloat("Coolant",999);tag.putInt("IndividualDoors",999);var copy=VehicleContent.NG_OFFROAD.get().create(h.getLevel());copy.systems.load(tag);h.assertTrue(copy.systems.mechanics.awd()&&copy.systems.mechanics.low()&&copy.systems.mechanics.manual()&&copy.systems.mechanics.gear()==2&&copy.systems.mechanics.radiator()==0&&copy.systems.mechanics.coolant()==5&&copy.systems.mechanics.temperature()==20&&copy.systems.mechanics.doorMask()==15,"Mechanics persistence/sanitization failed");c.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void missingReservedSemiPreventsStartingAndSecondCoupling(GameTestHelper h){var c=car(h,VehicleSpec.TRACTOR);var p=owner(h,c);var t=semi(h,c,p);c.systems.couple(p);t.toggleSupports(p);t.discard();h.assertFalse(c.systems.canRun()||c.systems.couple(p),"Missing reserved semi allowed drive or replacement coupling");c.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void semiFollowsActualForwardAndSteeringMovement(GameTestHelper h){var c=car(h,VehicleSpec.TRACTOR);var p=owner(h,c);var t=semi(h,c,p);h.assertTrue(c.systems.couple(p)&&t.toggleSupports(p),"Semi setup failed");start(c,p);var from=t.position();for(int i=0;i<65;i++){c.acceptInput(p,VehicleNetwork.FORWARD|(i>32?VehicleNetwork.LEFT:0));c.tick();t.tick();}h.assertTrue(c.engineRunning()&&c.systems.metres()>3&&t.position().distanceTo(from)>3,"Semi did not follow actual powered movement");h.assertTrue(Math.abs(c.getYRot())>5&&Math.abs(t.getYRot())>1,"Semi articulation did not follow steering");h.assertTrue(c.systems.trailerId().equals(t.getUUID())&&Math.abs(net.minecraft.util.Mth.wrapDegrees(c.getYRot()-t.getYRot()))<70,"Fifth wheel detached or folded");c.discard();t.discard();h.succeed();}
}
